from anthropic import Anthropic
client = Anthropic()

def is_abusive(message: str) -> bool:
    reply = client.messages.create(
        model="claude-sonnet-5",
        max_tokens=5,
        messages=[{"role": "user", "content": f"Is this message abusive? Answer only yes or no.\n\n{message}"}],
    )
    return reply.content[0].text.strip().lower().startswith("yes")
